KG_CODE("f:tests/test_desktop_batch.py","\"\"\"b25b-r: desktop.batch -- one adapter run_steps call behind the daemon's\nfull permission path (owner decisions D1+D2, 2026-10-12).\n\nD1: desktop.batch IS physical. daemon.py is NOT changed; the surface lock\n    (daemon.py:583) is held for the batch's whole life, including the time\n    parked on an ask. The lock tests pin the accepted serialization (another\n    physical verb queues) and the (b) proof (control frames still answer).\nD2: ONE line in safety/permissions.py -- VERB_RISK[\"desktop.batch\"] =\n    Risk.INPUT next to path.run/site.replay -- so a guarded batch of INPUT\n    steps never asks.\n\nSpec under test: desktop.batch {steps: [{ref, tool in click|double_click|\nright_click|set_value|type_text, args}], delay_ms?}; pre-dispatch refusals\n(effect none, nothing sent) for same-window, caps (steps <= 16, delay_ms*(steps-1) <= 4000) and\nper-step PermissionEngine.check() mapped to desktop.click/set_value/type\n(all-or-nothing; any needs_confirmation -> ONE combined ask via the\nConfirmationBroker; declined -> CONFIRMATION_DECLINED, nothing sent);\nrun_control.stopped() immediately before sending; ONE\ndriver_backend.try_call(\"run_steps\", ...) with the element_tokens + validated\nargs; per-step result rows (tool/ok/message/effect_state); batch effect_state\n= weakest across steps (none < unknown); timeout -> unknown for every step\n(K2d). Audit/feed: the existing writers, additive fields only.\n\"\"\"\nfrom __future__ import annotations\n\nimport json\nimport tempfile\nimport threading\nimport time\nimport os\nimport sys\nimport unittest\nfrom unittest.mock import patch\n\nfrom autoskill.desktop.driver_backend import DriverBackend\nfrom autoskill.resources import asset\nfrom pathlib import Path\nfrom unittest.mock import patch\n\nfrom autoskill.daemon import Daemon\nfrom autoskill.protocol import Request\nfrom autoskill.safety.permissions import (Decision, PermissionEngine,\n                                          PermissionMode, PermissionPolicy,\n                                          Risk, VERB_RISK, save_policy)\n\n# The step tools in the order the tests submit them; the mapped desktop.*\n# methods the permission engine must see (type_text -> desktop.type).\nSTEP_METHODS = (\"desktop.click\", \"desktop.set_value\", \"desktop.type\")\n\n\ndef _row(index, tool, ok=True, message=\"done\", effect=\"unknown\", **extra):\n    \"\"\"One entry of the adapter's run_steps report (protocol.rs:2108+),\n    already annotated with its effect_state (annotate_run_steps_reply).\"\"\"\n    row = {\"index\": index, \"tool\": tool, \"ok\": ok, \"message\": message,\n           \"effect_state\": effect}\n    row.update(extra)\n    return row\n\n\ndef _ok_batch_reply(rows):\n    \"\"\"A realistic adapter success envelope (driver_backend.try_call shape).\"\"\"\n    return {\"ok\": True, \"result\": {\"total\": len(rows),\n                                   \"executed\": sum(1 for r in rows if r.get(\"ok\")),\n                                   \"steps\": rows}}\n\n\n# The K2d envelope (tests/test_driver_actions.py:1420-1440 pin): a timed-out\n# run_steps is UNKNOWN for the whole batch -- any prefix may have dispatched.\n_TIMEOUT_REPLY = {\"ok\": False, \"error\": {\n    \"code\": \"driver_timeout\",\n    \"message\": \"SDK request deadline expired or worker stopped: timed out\",\n    \"effect_state\": \"unknown\", \"wants_foreground\": False, \"stale_element\": False}}\n\n\nclass _BatchDaemonBase(unittest.TestCase):\n    \"\"\"Shared plumbing: a real Daemon over a temp home (seam A), one session\n    whose ref store is seeded with driver-token refs (tests/test_driver_actions\n    .py:18-26 technique), and the patched single choke point every driver\n    reply flows through (driver_backend.try_call).\"\"\"\n\n    def setUp(self):\n        tmp = tempfile.TemporaryDirectory()\n        self.addCleanup(tmp.cleanup)\n        self.home = Path(tmp.name)\n        # confirm_timeout_s must live in the FILE: the first request of a\n        # fresh daemon always reloads the policy (daemon.py:289 starts\n        # _policy_mtime at 0.0), which replaces self.policy and would\n        # clobber an in-memory timeout back to the default 60 s.\n        save_policy(self.home, PermissionPolicy(mode=PermissionMode.GUARDED,\n                                                confirm_timeout_s=5))\n        self.d = Daemon(self.home)\n        self.addCleanup(self.d.shutdown)\n        # The dashboard opener must never run in a test (DB-07 precedent:\n        # tests/test_run_control.py:482).\n        self.d.run_control.dashboard_opener = lambda why: None\n        self.session = self.d.new_session()\n\n    def _persist(self):\n        \"\"\"Write the current in-memory policy back, so the per-request\n        reload keeps it (see setUp).\"\"\"\n        save_policy(self.d.home, self.d.policy)\n\n    def _mode(self, mode):\n        self.d.policy.mode = mode\n        save_policy(self.d.home, self.d.policy)\n\n    def call(self, method, params=None, session=True):\n        return self.d.handle(Request(method=method, params=params or {},\n                                     session=self.session.id if session else None,\n                                     id=\"t\"))\n\n    def _seed(self, *windows):\n        \"\"\"One observation, one ref per (pid, top_window, element_token);\n        refs in different windows share the generation (refs.py:116-126).\"\"\"\n        store = self.session.ref_store\n        store.begin_observation()\n        refs = []\n        for i, (pid, top, token) in enumerate(windows):\n            refs.append(store.add(None, role=\"button\", name=f\"Target {i}\",\n                                  element_token=token, window_pid=pid,\n                                  top_window=top, process=\"app.exe\",\n                                  window_title=\"App\"))\n        return refs\n\n    @staticmethod\n    def _batch(plan, delay_ms=None):\n        params = {\"steps\": [{\"ref\": ref, \"tool\": tool, \"args\": dict(args or {})}\n                            for ref, tool, args in plan]}\n        if delay_ms is not None:\n            params[\"delay_ms\"] = delay_ms\n        return params\n\n    @staticmethod\n    def _patch_try_call(reply):\n        return patch(\"autoskill.desktop.driver_backend.try_call\",\n                     return_value=reply)\n\n    def _force_step_confirmation(self):\n        \"\"\"Force ONLY the per-step checks to need confirmation.\n\n        Guarded mode never confirms INPUT steps (that is the zero-ask test's\n        pin) and strict mode would stack the daemon's own method-level ask on\n        top (daemon.py:686-703), so neither isolates the handler's combined\n        ask with EXACTLY ONE ask parked. The honest isolation is the\n        pure-engine override the suite already uses\n        (tests/test_driver_windows.py:293-301, tests/test_core.py:820-834):\n        the mapped step methods confirm, everything else -- desktop.batch\n        itself included -- delegates to the real engine. The ask still runs\n        through the real ConfirmationBroker and the real timeout.\"\"\"\n        engine_cls = type(self.d.permissions)\n        original = engine_cls.check\n        mapped_seen = []\n\n        def forcing(engine, method, **kw):\n            if method in STEP_METHODS:\n                mapped_seen.append(method)\n                return Decision(True, needs_confirmation=True,\n                                reason=\"input action requires approval\",\n                                risk=Risk.INPUT)\n            return original(engine, method, **kw)\n\n        return mapped_seen, patch.object(engine_cls, \"check\", forcing)\n\n    def _spy_asks(self):\n        \"\"\"Record every broker ask (and still perform it for real).\"\"\"\n        real_ask = self.d.confirmations.ask\n        asks = []\n\n        def spy_ask(**kw):\n            asks.append(kw)\n            return real_ask(**kw)\n\n        return asks, patch.object(self.d.confirmations, \"ask\", spy_ask)\n\n    def _answer_pending(self, granted):\n        for c in self.d.confirmations.pending():\n            self.d.confirmations.answer(c[\"token\"], granted)\n\n    def _answer_when_parked(self, granted, record=None, timeout=5.0):\n        \"\"\"Answer the batch's ask the moment it parks -- robust against the\n        first desktop dispatch's import warm-up, which a blind Timer can\n        lose. Optionally records the parked snapshot for the one-ask pin.\"\"\"\n        def answerer():\n            deadline = time.monotonic() + timeout\n            while time.monotonic() < deadline:\n                pending = self.d.confirmations.pending()\n                if pending:\n                    if record is not None:\n                        record[\"pending\"] = pending\n                    self._answer_pending(granted)\n                    return\n                time.sleep(0.02)\n        threading.Thread(target=answerer, daemon=True).start()\n\n\nclass DesktopBatchDaemonTests(_BatchDaemonBase):\n    \"\"\"The runner-level pins, through the full production path: validate ->\n    gate -> surface lock -> outer check -> dispatch -> handler.\"\"\"\n\n    def test_mixed_window_refs_are_refused_before_dispatch(self):\n        self._mode(PermissionMode.FULL)\n        here, other = self._seed((100, 77, \"s00000042:1\"),\n                                 (101, 88, \"s00000099:1\"))\n        params = self._batch([(here, \"click\", {}), (other, \"type_text\", {\"text\": \"x\"})])\n        with self._patch_try_call(_ok_batch_reply([_row(0, \"click\")])) as call:\n            response = self.call(\"desktop.batch\", params)\n        self.assertFalse(response.ok)\n        self.assertEqual(response.error[\"effect_state\"], \"none\")\n        self.assertIn(\"window\", response.error[\"message\"].lower())\n        call.assert_not_called()                      # nothing was sent\n\n    def test_unknown_ref_refuses_the_whole_batch(self):\n        self._mode(PermissionMode.FULL)\n        good, = self._seed((100, 77, \"s00000042:1\"))\n        params = self._batch([(good, \"click\", {}), (\"@e999\", \"click\", {})])\n        with self._patch_try_call(_ok_batch_reply([_row(0, \"click\")])) as call:\n            response = self.call(\"desktop.batch\", params)\n        self.assertFalse(response.ok)\n        self.assertEqual(response.error[\"effect_state\"], \"none\")\n        self.assertIn(\"@e999\", response.error[\"message\"])   # names the offender\n        call.assert_not_called()\n\n    def test_step_cap_16_is_the_maximum(self):\n        self._mode(PermissionMode.FULL)\n        ref, = self._seed((100, 77, \"s00000042:1\"))\n        over = self._batch([(ref, \"click\", {})] * 17)\n        with self._patch_try_call(_ok_batch_reply([_row(0, \"click\")])) as call:\n            response = self.call(\"desktop.batch\", over)\n        self.assertFalse(response.ok)\n        self.assertEqual(response.error[\"effect_state\"], \"none\")\n        self.assertIn(\"16\", response.error[\"message\"])\n        call.assert_not_called()\n        # Boundary: 16 steps is legal and dispatches exactly once.\n        boundary = self._batch([(ref, \"click\", {})] * 16)\n        with self._patch_try_call(_ok_batch_reply([_row(i, \"click\")\n                                                   for i in range(16)])) as call:\n            accepted = self.call(\"desktop.batch\", boundary)\n        self.assertTrue(accepted.ok, accepted.error)\n        call.assert_called_once()\n\n    def test_delay_budget_4000ms_is_the_maximum(self):\n        self._mode(PermissionMode.FULL)\n        ref, = self._seed((100, 77, \"s00000042:1\"))\n        # 4 steps x 1334 ms gaps = 4002 > 4000, with a per-step delay the\n        # adapter itself would accept (<= MAX_DELAY_MS 2000): the Python\n        # budget is the binding cap.\n        over = self._batch([(ref, \"click\", {})] * 4, delay_ms=1334)\n        with self._patch_try_call(_ok_batch_reply([_row(0, \"click\")])) as call:\n            response = self.call(\"desktop.batch\", over)\n        self.assertFalse(response.ok)\n        self.assertEqual(response.error[\"effect_state\"], \"none\")\n        self.assertIn(\"4000\", response.error[\"message\"])\n        call.assert_not_called()\n        # Boundary: 3 steps x 2000 ms gaps = exactly 4000 is accepted.\n        boundary = self._batch([(ref, \"click\", {})] * 3, delay_ms=2000)\n        with self._patch_try_call(_ok_batch_reply([_row(0, \"click\")])) as call:\n            accepted = self.call(\"desktop.batch\", boundary)\n        self.assertTrue(accepted.ok, accepted.error)\n        call.assert_called_once()\n\n    def test_per_step_checks_ask_once_combining_every_step(self):\n        r1, r2, r3 = self._seed((100, 77, \"s00000042:1\"), (100, 77, \"s00000043:1\"),\n                                (100, 77, \"s00000044:1\"))\n        params = self._batch([(r1, \"click\", {}), (r2, \"set_value\", {\"value\": \"v\"}),\n                              (r3, \"type_text\", {\"text\": \"hello\"})], delay_ms=25)\n        mapped, forcing = self._force_step_confirmation()\n        asks, ask_spy = self._spy_asks()\n        parked = {}\n        self._answer_when_parked(True, record=parked)\n        with forcing, ask_spy, self._patch_try_call(_ok_batch_reply(\n                [_row(0, \"click\"), _row(1, \"set_value\"), _row(2, \"type_text\")])) as call:\n            response = self.call(\"desktop.batch\", params)\n        self.assertTrue(response.ok, response.error)\n        # All-or-nothing: each step checked once, mapped tool -> method in\n        # order (type_text maps to desktop.type).\n        self.assertEqual(mapped, list(STEP_METHODS))\n        # EXACTLY ONE ask -- the combined one, listing every step.\n        self.assertEqual(len(asks), 1)\n        self.assertEqual(asks[0][\"method\"], \"desktop.batch\")\n        for tool in (\"click\", \"set_value\", \"type_text\"):\n            self.assertIn(tool, asks[0][\"detail\"])\n        self.assertEqual(len(parked.get(\"pending\", [])), 1)\n        # ONE dispatch carrying every step.\n        self.assertEqual(call.call_count, 1,  # fx10: the send only, no read-back (as CUA)\n                         'the batch send and no window_state read')\n        self.assertEqual(call.call_args_list[0][0][0], \"run_steps\")  # b25c: send first\n        self.assertEqual(len(call.call_args_list[0][0][1][\"steps\"]), 3)\n\n    def test_unanswered_ask_declines_with_nothing_sent(self):\n        self.d.policy.confirm_timeout_s = 1\n        self._persist()                      # the per-request reload keeps 1 s\n        ref, = self._seed((100, 77, \"s00000042:1\"))\n        params = self._batch([(ref, \"click\", {})])\n        mapped, forcing = self._force_step_confirmation()\n        with forcing, self._patch_try_call(_ok_batch_reply([_row(0, \"click\")])) as call:\n            response = self.call(\"desktop.batch\", params)   # nobody answers\n        self.assertEqual(mapped, [\"desktop.click\"])        # the step WAS checked\n        self.assertFalse(response.ok)\n        self.assertEqual(response.error[\"code\"], \"confirmation_declined\")\n        self.assertEqual(response.error[\"effect_state\"], \"none\")\n        call.assert_not_called()\n        rows = [r for r in self.call(\"_run.state\").result[\"feed\"]\n                if r.get(\"method\") == \"desktop.batch\"]\n        self.assertTrue(rows and rows[-1][\"outcome\"] == \"error\")\n\n    def test_denied_answer_is_confirmation_declined(self):\n        ref, = self._seed((100, 77, \"s00000042:1\"))\n        params = self._batch([(ref, \"click\", {}), (ref, \"set_value\", {\"value\": \"v\"})])\n        mapped, forcing = self._force_step_confirmation()\n        self._answer_when_parked(False)\n        with forcing, self._patch_try_call(_ok_batch_reply([_row(0, \"click\")])) as call:\n            response = self.call(\"desktop.batch\", params)   # the dashboard Deny\n        self.assertEqual(mapped, [\"desktop.click\", \"desktop.set_value\"])\n        self.assertFalse(response.ok)\n        self.assertEqual(response.error[\"code\"], \"confirmation_declined\")\n        self.assertEqual(response.error[\"effect_state\"], \"none\")\n        call.assert_not_called()\n\n    def test_stop_between_grant_and_send_refuses_the_batch(self):\n        ref, = self._seed((100, 77, \"s00000042:1\"))\n        params = self._batch([(ref, \"click\", {}), (ref, \"set_value\", {\"value\": \"v\"})])\n        mapped, forcing = self._force_step_confirmation()\n        # The grant frees the parked ask; Stop then lands ON the handler\n        # thread, strictly between the ask and the stopped() checkpoint --\n        # no race, the checkpoint itself is what must refuse.\n        real_ask = self.d.confirmations.ask\n\n        def ask_then_stop(**kw):\n            granted = real_ask(**kw)\n            self.d.run_control.stop(self.d.confirmations)\n            return granted\n\n        self._answer_when_parked(True)\n        with forcing, patch.object(self.d.confirmations, \"ask\", ask_then_stop), \\\n                self._patch_try_call(_ok_batch_reply([_row(0, \"click\")])) as call:\n            response = self.call(\"desktop.batch\", params)\n        call.assert_not_called()                          # nothing was sent\n        self.assertEqual(mapped, [\"desktop.click\", \"desktop.set_value\"])\n        self.assertFalse(response.ok)\n        self.assertEqual(response.error[\"effect_state\"], \"none\")\n        self.assertIn(\"stop\", response.error[\"message\"].lower())\n\n    def test_stop_before_the_request_refuses_at_the_gate(self):\n        self._mode(PermissionMode.FULL)\n        ref, = self._seed((100, 77, \"s00000042:1\"))\n        self.assertTrue(self.call(\"_run.stop\", session=None).ok)\n        with self._patch_try_call(_ok_batch_reply([_row(0, \"click\")])) as call:\n            response = self.call(\"desktop.batch\", self._batch([(ref, \"click\", {})]))\n        self.assertFalse(response.ok)\n        self.assertEqual(response.error[\"code\"], \"permission_denied\")\n        self.assertIn(\"resume\", json.dumps(response.error).lower())\n        call.assert_not_called()\n        self.assertTrue(self.call(\"_run.resume\", session=None).ok)\n\n    def test_guarded_batch_of_input_steps_never_asks(self):\n        \"\"\"The D2 pin: INPUT is not in GUARDED_CONFIRM_RISKS\n        (permissions.py:230), so neither the outer desktop.batch check nor\n        any per-step desktop.click/set_value/type check asks.\"\"\"\n        r1, r2, r3 = self._seed((100, 77, \"s00000042:1\"), (100, 77, \"s00000043:1\"),\n                                (100, 77, \"s00000044:1\"))\n        params = self._batch([(r1, \"click\", {}), (r2, \"set_value\", {\"value\": \"v\"}),\n                              (r3, \"type_text\", {\"text\": \"t\"})], delay_ms=10)\n        asks, ask_spy = self._spy_asks()\n        with ask_spy, self._patch_try_call(_ok_batch_reply(\n                [_row(0, \"click\"), _row(1, \"set_value\"), _row(2, \"type_text\")])) as call:\n            response = self.call(\"desktop.batch\", params)\n        self.assertTrue(response.ok, response.error)\n        self.assertEqual(asks, [])                       # ZERO asks in guarded\n        self.assertEqual(self.d.confirmations.pending(), [])\n        self.assertEqual(call.call_count, 1,  # fx10: the send only, no read-back (as CUA)\n                         'the batch send and no window_state read')\n        self.assertEqual(call.call_args_list[0][0][0], \"run_steps\")  # b25c: send first\n        self.assertEqual(response.result.get(\"effect_state\"), \"unknown\")\n        feed = self.call(\"_run.state\").result[\"feed\"]\n        self.assertFalse(any(r.get(\"kind\") == \"approval\" for r in feed))\n        self.assertFalse(any(r.get(\"approval\") for r in feed))\n\n    def test_result_rows_map_from_the_run_steps_reply(self):\n        self._mode(PermissionMode.FULL)\n        r1, r2, r3 = self._seed((100, 77, \"s00000042:1\"), (100, 77, \"s00000043:1\"),\n                                (100, 77, \"s00000044:1\"))\n        rows = [_row(0, \"click\", message=\"on OK in App\", effect=\"unknown\"),\n                _row(1, \"set_value\", message=\"value set\", effect=\"unknown\"),\n                _row(2, \"type_text\", ok=False,\n                     message=\"no element matched role textbox name Field\",\n                     effect=\"none\")]\n        params = self._batch([(r1, \"click\", {}), (r2, \"set_value\", {\"value\": \"v\"}),\n                              (r3, \"type_text\", {\"text\": \"t\"})], delay_ms=50)\n        with self._patch_try_call(_ok_batch_reply(rows)) as call:\n            response = self.call(\"desktop.batch\", params)\n        self.assertTrue(response.ok, response.error)\n        out = response.result[\"steps\"]\n        self.assertEqual([r[\"tool\"] for r in out], [\"click\", \"set_value\", \"type_text\"])\n        self.assertEqual([r[\"ok\"] for r in out], [True, True, False])\n        self.assertEqual([r[\"message\"] for r in out],\n                         [\"on OK in App\", \"value set\",\n                          \"no element matched role textbox name Field\"])\n        self.assertEqual([r[\"effect_state\"] for r in out],\n                         [\"unknown\", \"unknown\", \"none\"])\n        # b25b-fix2 (G2): the owner's truth table replaces min() - a mix of\n        # ran (unknown) and not-run (none) steps is \"unknown\", never a\n        # false safe-to-retry \"none\".\n        self.assertEqual(response.result[\"effect_state\"], \"unknown\")\n        # The wire grammar (protocol.rs run_steps_params): the shared window\n        # identity, tool+args steps carrying the element_tokens, delay.\n        self.assertEqual(call.call_count, 1,  # fx10: the send only, no read-back (as CUA)\n                         'the batch send and no window_state read')\n        self.assertEqual(call.call_args_list[0][0][0], \"run_steps\")  # b25c: send first\n        sent = call.call_args_list[0][0][1]\n        self.assertEqual((sent[\"pid\"], sent[\"window_id\"]), (100, 77))\n        self.assertEqual([s[\"tool\"] for s in sent[\"steps\"]],\n                         [\"click\", \"set_value\", \"type_text\"])\n        self.assertEqual([s[\"args\"].get(\"element_token\") for s in sent[\"steps\"]],\n                         [\"s00000042:1\", \"s00000043:1\", \"s00000044:1\"])\n        self.assertEqual(sent.get(\"delay_ms\"), 50)\n        # The foreground opt-in stays AutoSkill's: the wire never sets it.\n        self.assertFalse(sent.get(\"foreground_fallback\", False))\n\n    def test_driver_timeout_is_unknown_for_every_step(self):\n        self._mode(PermissionMode.FULL)\n        ref, = self._seed((100, 77, \"s00000042:1\"))\n        params = self._batch([(ref, \"click\", {}), (ref, \"type_text\", {\"text\": \"x\"})])\n        with self._patch_try_call(_TIMEOUT_REPLY) as call:\n            response = self.call(\"desktop.batch\", params)\n        call.assert_called_once()                 # K2d: never replayed\n        self.assertTrue(response.ok, response.error)\n        self.assertEqual(response.result[\"effect_state\"], \"unknown\")\n        self.assertEqual(response.result.get(\"code\"), \"driver_timeout\")\n        rows = response.result[\"steps\"]\n        self.assertEqual([r[\"effect_state\"] for r in rows],\n                         [\"unknown\", \"unknown\"])   # K2d: every step unknown\n        # Nothing in the batch's own report may claim \"none\": a duplicate\n        # send after a timeout is the classic silent double-input. (The\n        # daemon's additive memory fields around the result are out of\n        # scope here -- the report is what decides a retry.)\n        report_effects = ({response.result[\"effect_state\"]}\n                          | {r[\"effect_state\"] for r in rows})\n        self.assertNotIn(\"none\", report_effects)\n\n    def test_unavailable_driver_refuses_the_batch_honestly(self):\n        self._mode(PermissionMode.FULL)\n        ref, = self._seed((100, 77, \"s00000042:1\"))\n        params = self._batch([(ref, \"click\", {})])\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=None) as call:\n            response = self.call(\"desktop.batch\", params)\n        self.assertTrue(response.ok, response.error)\n        self.assertEqual(response.result[\"effect_state\"], \"none\")  # nothing sent\n        self.assertFalse(response.result.get(\"sent\"))\n        self.assertIn(\"unavailable\",\n                      str(response.result.get(\"reason\", \"\")).lower())\n        self.assertEqual([r[\"effect_state\"] for r in response.result[\"steps\"]],\n                         [\"none\"])\n        call.assert_called_once()                 # one honest try, no storm\n\n    def test_malformed_steps_refuse_before_send(self):\n        self._mode(PermissionMode.FULL)\n        ref, = self._seed((100, 77, \"s00000042:1\"))\n        with self._patch_try_call(_ok_batch_reply([_row(0, \"click\")])) as call:\n            unknown_tool = self.call(\"desktop.batch\", {\"steps\": [\n                {\"ref\": ref, \"tool\": \"scroll\", \"args\": {}}]})\n            missing_ref = self.call(\"desktop.batch\", {\"steps\": [\n                {\"tool\": \"click\", \"args\": {}}]})\n            empty = self.call(\"desktop.batch\", {\"steps\": []})\n        for response in (unknown_tool, missing_ref, empty):\n            self.assertFalse(response.ok)\n            self.assertEqual(response.error[\"effect_state\"], \"none\")\n        self.assertIn(\"steps[0]\", unknown_tool.error[\"message\"])\n        self.assertIn(\"steps[0]\", missing_ref.error[\"message\"])\n        call.assert_not_called()\n\n\nclass TestB4cDedicatedStepTools(_BatchDaemonBase):\n    \"\"\"b4c: run_steps accepts double_click/right_click (BATCHABLE_TOOLS,\n    batch_tools.rs:32-43 at pin 815dfd96), so desktop.batch gains them —\n    mapped to desktop.click permission semantics, pid injected like\n    set_value.\"\"\"\n\n    def test_dedicated_step_tools_run_and_carry_pid_on_the_wire(self):\n        self._mode(PermissionMode.FULL)\n        r1, r2 = self._seed((100, 77, \"s00000042:1\"), (100, 77, \"s00000042:2\"))\n        with self._patch_try_call(_ok_batch_reply(\n                [_row(0, \"double_click\"), _row(1, \"right_click\")])) as call:\n            response = self.call(\"desktop.batch\", self._batch(\n                [(r1, \"double_click\", {}), (r2, \"right_click\", {})]))\n        self.assertTrue(response.ok, response.error)\n        call.assert_called_once()\n        self.assertEqual(call.call_args_list[0][0][0], \"run_steps\")\n        wire = call.call_args_list[0][0][1]\n        self.assertEqual((wire[\"pid\"], wire[\"window_id\"]), (100, 77))\n        self.assertEqual([s[\"tool\"] for s in wire[\"steps\"]],\n                         [\"double_click\", \"right_click\"])\n        # element_token + pid injected exactly like set_value's step\n        # (batch.py): the schema requires pid.\n        self.assertEqual([s[\"args\"][\"element_token\"] for s in wire[\"steps\"]],\n                         [\"s00000042:1\", \"s00000042:2\"])\n        self.assertEqual([s[\"args\"][\"pid\"] for s in wire[\"steps\"]],\n                         [100, 100])\n        # The reply rows map by index as usual.\n        self.assertEqual([r[\"tool\"] for r in response.result[\"steps\"]],\n                         [\"double_click\", \"right_click\"])\n        self.assertEqual([r[\"effect_state\"] for r in response.result[\"steps\"]],\n                         [\"unknown\", \"unknown\"])\n\n    def test_dedicated_step_tools_map_to_desktop_click_permissions(self):\n        # The step tools' permission semantics are a CLICK's: the engine\n        # sees desktop.click for both, never a new verb (permissions.py\n        # itself is untouched — the map's MUST STAY IDENTICAL list).\n        self._mode(PermissionMode.FULL)\n        r1, r2 = self._seed((100, 77, \"s00000042:1\"), (100, 77, \"s00000042:2\"))\n        engine_cls = type(self.d.permissions)\n        original = engine_cls.check\n        seen = []\n\n        def recording(engine, method, **kw):\n            seen.append(method)\n            return original(engine, method, **kw)\n\n        with patch.object(engine_cls, \"check\", recording), \\\n                self._patch_try_call(_ok_batch_reply(\n                    [_row(0, \"double_click\"), _row(1, \"right_click\")])):\n            response = self.call(\"desktop.batch\", self._batch(\n                [(r1, \"double_click\", {}), (r2, \"right_click\", {})]))\n        self.assertTrue(response.ok, response.error)\n        # The daemon's own outer desktop.batch check aside (it consults\n        # the engine twice in this harness: the dispatch gate and the\n        # handler's enforce), the ONLY step methods checked are\n        # desktop.click — one per step, in order.\n        self.assertEqual([m for m in seen if m != \"desktop.batch\"],\n                         [\"desktop.click\", \"desktop.click\"])\n        self.assertGreaterEqual(seen.count(\"desktop.batch\"), 1)\n        self.assertEqual(set(seen),\n                         {\"desktop.batch\", \"desktop.click\"})\n\n    def test_unknown_tool_refusal_now_names_the_dedicated_tools(self):\n        # Unknown tools keep being refused pre-dispatch (the message lists\n        # sorted(_STEP_METHOD), which now includes the new tools).\n        self._mode(PermissionMode.FULL)\n        ref, = self._seed((100, 77, \"s00000042:1\"))\n        with self._patch_try_call(_ok_batch_reply([_row(0, \"click\")])) as call:\n            response = self.call(\"desktop.batch\", {\"steps\": [\n                {\"ref\": ref, \"tool\": \"scroll\", \"args\": {}}]})\n        self.assertFalse(response.ok)\n        self.assertEqual(response.error[\"effect_state\"], \"none\")\n        self.assertIn(\"steps[0]\", response.error[\"message\"])\n        self.assertIn(\"double_click\", response.error[\"message\"])\n        self.assertIn(\"right_click\", response.error[\"message\"])\n        call.assert_not_called()\n\n    def test_describe_steps_renders_the_dedicated_tools(self):\n        from autoskill.desktop.batch import describe_steps\n        r1, r2 = self._seed((100, 77, \"s00000042:1\"), (100, 77, \"s00000042:2\"))\n        detail, mirror_detail = describe_steps(self.session, {\"steps\": [\n            {\"ref\": r1, \"tool\": \"double_click\", \"args\": {}},\n            {\"ref\": r2, \"tool\": \"right_click\", \"args\": {}}]})\n        self.assertTrue(detail.startswith(\"desktop.batch steps: \"))\n        self.assertIn(f\"double_click on {r1} button 'Target 0'\", detail)\n        self.assertIn(f\"right_click on {r2} button 'Target 1'\", detail)\n        self.assertEqual(mirror_detail, detail)\n\n    def test_describe_steps_live_shows_args_mirror_is_argument_free(self):\n        from autoskill.desktop.batch import describe_steps\n        r1, r2, r3 = self._seed((100, 77, \"s00000042:1\"),\n                                (100, 77, \"s00000042:2\"),\n                                (100, 77, \"s00000042:3\"))\n        live, mirror = describe_steps(self.session, {\"steps\": [\n            {\"ref\": r1, \"tool\": \"click\",\n             \"args\": {\"count\": 2, \"button\": \"right\", \"modifier\": [\"ctrl\"]}},\n            {\"ref\": r2, \"tool\": \"set_value\", \"args\": {\"value\": \"v\"}},\n            {\"ref\": r3, \"tool\": \"type_text\", \"args\": {\"text\": \"hello\"}}]})\n        self.assertTrue(live.startswith(\"desktop.batch steps: \"))\n        self.assertIn(f\"click on {r1} button 'Target 0' \"\n                      \"(args: count=2, button='right', modifier=['ctrl'])\", live)\n        self.assertIn(f\"set_value on {r2} button 'Target 1' (args: value='v')\",\n                      live)\n        self.assertIn(f\"type_text on {r3} button 'Target 2' (args: text='hello')\",\n                      live)\n        # THE MIRROR: exactly today's argument-free text, byte for byte.\n        self.assertEqual(mirror,\n                         f\"desktop.batch steps: click on {r1} button 'Target 0'; \"\n                         f\"set_value on {r2} button 'Target 1'; \"\n                         f\"type_text on {r3} button 'Target 2'\")\n        self.assertNotIn(\"(args:\", mirror)\n\n    def test_describe_steps_no_args_live_and_mirror_identical(self):\n        from autoskill.desktop.batch import describe_steps\n        r, = self._seed((100, 77, \"s00000042:1\"))\n        live, mirror = describe_steps(self.session, {\"steps\": [\n            {\"ref\": r, \"tool\": \"click\", \"args\": {}}]})\n        self.assertEqual(live, f\"desktop.batch steps: click on {r} button 'Target 0'\")\n        self.assertEqual(mirror, live)\n\n    def test_describe_steps_unresolvable_ref_wording_plus_args_live_only(self):\n        from autoskill.desktop.batch import describe_steps\n        live, mirror = describe_steps(self.session, {\"steps\": [\n            {\"ref\": \"@e999\", \"tool\": \"click\", \"args\": {\"count\": 3}}]})\n        self.assertEqual(live,\n                         \"desktop.batch steps: click on @e999 \"\n                         \"(unresolvable ref) (args: count=3)\")\n        self.assertEqual(mirror,\n                         \"desktop.batch steps: click on @e999 (unresolvable ref)\")\n\n\n    def test_handler_combined_ask_live_shows_args_mirror_does_not(self):\n        r1, r2, r3 = self._seed((100, 77, \"s00000042:1\"), (100, 77, \"s00000042:2\"),\n                                (100, 77, \"s00000042:3\"))\n        params = self._batch([(r1, \"click\", {}),\n                              (r2, \"set_value\", {\"value\": \"s3cret-value\"}),\n                              (r3, \"type_text\", {\"text\": \"hello\"})], delay_ms=25)\n        mapped, forcing = self._force_step_confirmation()\n        asks, ask_spy = self._spy_asks()\n        self._answer_when_parked(True)\n        with forcing, ask_spy, self._patch_try_call(_ok_batch_reply(\n                [_row(0, \"click\"), _row(1, \"set_value\"), _row(2, \"type_text\")])):\n            response = self.call(\"desktop.batch\", params)\n        self.assertTrue(response.ok, response.error)\n        self.assertEqual(len(asks), 1)\n        # LIVE line: each needing step carries its own args.\n        self.assertTrue(asks[0][\"detail\"].startswith(\n            \"desktop.batch steps requiring approval: \"))\n        self.assertIn(f\"click on {r1} button 'Target 0'\", asks[0][\"detail\"])\n        self.assertIn(f\"set_value on {r2} button 'Target 1' \"\n                      \"(args: value='s3cret-value')\", asks[0][\"detail\"])\n        self.assertIn(f\"type_text on {r3} button 'Target 2' \"\n                      \"(args: text='hello')\", asks[0][\"detail\"])\n        # MIRROR line handed to the broker: today's argument-free text exactly.\n        self.assertEqual(\n            asks[0][\"mirror_detail\"],\n            \"desktop.batch steps requiring approval: \"\n            f\"click on {r1} button 'Target 0'; \"\n            f\"set_value on {r2} button 'Target 1'; \"\n            f\"type_text on {r3} button 'Target 2'\")\n\nclass DesktopBatchSurfaceLockTests(_BatchDaemonBase):\n    \"\"\"D1: the batch is physical, so _surface_lock (daemon.py:583) is held\n    for its whole life -- including the time parked on an ask. Pinned at test\n    level: (b) control frames (non-physical methods) still answer while a\n    batch is parked; and the accepted serialization -- another physical verb\n    queues behind the parked batch until it finishes.\"\"\"\n\n    def setUp(self):\n        super().setUp()\n        self.d.policy.confirm_timeout_s = 10   # the parked ask outlives the\n        self._persist()                        # test's timing windows\n\n    def _wait_parked(self, want=1, timeout=3.0):\n        deadline = time.monotonic() + timeout\n        while time.monotonic() < deadline:\n            if len(self.d.confirmations.pending()) >= want:\n                return True\n            time.sleep(0.02)\n        return False\n\n    def test_control_frames_pass_while_a_batch_is_parked_on_its_ask(self):\n        self._mode(PermissionMode.STRICT)   # the real path: the daemon's own\n        ref, = self._seed((100, 77, \"s00000042:1\"))   # outer ask parks it\n        outcome = {}\n\n        def run_batch():\n            with self._patch_try_call(_ok_batch_reply([_row(0, \"click\")])):\n                outcome[\"resp\"] = self.call(\"desktop.batch\",\n                                            self._batch([(ref, \"click\", {})]))\n\n        runner = threading.Thread(target=run_batch, daemon=True)\n        runner.start()\n        self.assertTrue(self._wait_parked(), \"the batch must park on its ask\")\n        parked = self.d.confirmations.pending()\n        self.assertEqual(len(parked), 1)\n        self.assertEqual(parked[0][\"method\"], \"desktop.batch\")\n        started = time.monotonic()\n        ping = self.d.handle(Request(\"system.ping\", id=\"ping\"))\n        state = self.d.handle(Request(\"_run.state\", id=\"state\"))\n        self.assertTrue(ping.ok)\n        self.assertTrue(state.ok)\n        self.assertLess(time.monotonic() - started, 2)   # passed while parked\n        self._answer_pending(False)                      # drain: declined\n        runner.join(5)\n        self.assertFalse(outcome[\"resp\"].ok)  # declined -- not this test's point\n\n    def test_physical_verb_waits_while_the_batch_holds_the_surface_lock(self):\n        self._mode(PermissionMode.FULL)     # the daemon's outer check stays\n        ref, = self._seed((100, 77, \"s00000042:1\"))  # quiet; the forcing patch\n        entered = threading.Event()         # parks the batch on its combined ask\n        self.d.register(\"desktop.fixture\",\n                        lambda s, p: (entered.set(), {\"effect_state\": \"none\"})[1])\n        mapped, forcing = self._force_step_confirmation()\n        outcome = {}\n\n        def run_batch():\n            outcome[\"resp\"] = self.call(\"desktop.batch\",\n                                        self._batch([(ref, \"click\", {})]))\n\n        def run_fixture():\n            outcome[\"fixture\"] = self.d.handle(Request(\n                \"desktop.fixture\", session=self.session.id, id=\"fx\"))\n            done.set()\n\n        done = threading.Event()\n        runner = threading.Thread(target=run_batch, daemon=True)\n        with forcing, self._patch_try_call(_ok_batch_reply([_row(0, \"click\")])):\n            runner.start()\n            self.assertTrue(self._wait_parked(), \"the batch must park on its ask\")\n            waiter = threading.Thread(target=run_fixture, daemon=True)\n            waiter.start()\n            # D1's accepted cost: the physical verb queues on _surface_lock\n            # for as long as the batch is parked on a human decision.\n            self.assertFalse(done.wait(0.4),\n                             \"a physical verb must queue behind the parked batch\")\n            self.assertFalse(entered.is_set())\n            self._answer_pending(True)                   # grant; batch sends,\n            runner.join(5)                               # finishes, releases\n            waiter.join(5)\n        self.assertTrue(done.is_set())\n        self.assertTrue(entered.is_set())\n        self.assertTrue(outcome[\"resp\"].ok, outcome[\"resp\"].error)\n        self.assertTrue(outcome[\"fixture\"].ok, outcome[\"fixture\"].error)\n\n\nclass DesktopBatchRiskPinTests(unittest.TestCase):\n    \"\"\"D2's one line, pinned directly on the pure engine.\"\"\"\n\n    def test_desktop_batch_is_input_risk_and_guarded_never_confirms(self):\n        self.assertIs(VERB_RISK.get(\"desktop.batch\"), Risk.INPUT)\n        engine = PermissionEngine(PermissionPolicy(mode=PermissionMode.GUARDED))\n        self.assertIs(engine.risk_of(\"desktop.batch\"), Risk.INPUT)\n        decision = engine.check(\"desktop.batch\", process=\"app.exe\", title=\"App\")\n        self.assertTrue(decision.allowed)\n        self.assertFalse(decision.needs_confirmation)   # INPUT is not in\n        self.assertIs(decision.risk, Risk.INPUT)        # GUARDED_CONFIRM_RISKS\n        strict = PermissionEngine(PermissionPolicy(mode=PermissionMode.STRICT))\n        self.assertTrue(strict.check(\"desktop.batch\").needs_confirmation)\n\n\nclass DesktopBatchAuditFeedTests(_BatchDaemonBase):\n    \"\"\"Item 5: the batch flows through the EXISTING audit/feed writers, and\n    whatever per-step detail is exposed is additive only.\"\"\"\n\n    def test_batch_reaches_the_existing_audit_and_feed_writers(self):\n        self._mode(PermissionMode.FULL)\n        r1, r2, r3 = self._seed((100, 77, \"s00000042:1\"), (100, 77, \"s00000043:1\"),\n                                (100, 77, \"s00000044:1\"))\n        params = self._batch([(r1, \"click\", {}),\n                              (r2, \"set_value\", {\"value\": \"v\"}),\n                              (r3, \"type_text\", {\"text\": \"s3cret-value\"})])\n        # A baseline row from the same existing writer, for the additive pin.\n        self.assertTrue(self.call(\"system.status\", session=None).ok)\n        baseline = set([r for r in self.call(\"_run.state\", session=None).result[\"feed\"]\n                        if r.get(\"method\") == \"system.status\"][-1])\n\n        notes, audits = [], []\n        real_note = self.d.run_control.note_request\n        real_record = self.d.audit.record\n\n        def spy_note(**kw):\n            notes.append(kw)\n            return real_note(**kw)\n\n        def spy_record(**kw):\n            audits.append(kw)\n            return real_record(**kw)\n\n        with patch.object(self.d.run_control, \"note_request\", spy_note), \\\n                patch.object(self.d.audit, \"record\", spy_record), \\\n                self._patch_try_call(_ok_batch_reply(\n                    [_row(0, \"click\"), _row(1, \"set_value\"), _row(2, \"type_text\")])):\n            response = self.call(\"desktop.batch\", params)\n        self.assertTrue(response.ok, response.error)\n\n        # The existing feed writer notes the request once.\n        batch_notes = [n for n in notes if n.get(\"method\") == \"desktop.batch\"]\n        self.assertEqual(len(batch_notes), 1)\n        self.assertEqual(batch_notes[0][\"outcome\"], \"ok\")\n\n        # The existing audit writer receives the batch result carrying the\n        # per-step rows (what it keeps is its own summarise filter).\n        batch_audits = [a for a in audits if a.get(\"method\") == \"desktop.batch\"]\n        self.assertEqual(len(batch_audits), 1)\n        self.assertEqual(batch_audits[0][\"outcome\"], \"ok\")\n        sent_result = batch_audits[0].get(\"result\") or {}\n        self.assertEqual(len(sent_result.get(\"steps\") or []), 3)\n\n        # Additive only: the feed row keeps the base schema (nothing removed).\n        feed = self.call(\"_run.state\", session=None).result[\"feed\"]\n        batch_row = [r for r in feed if r.get(\"method\") == \"desktop.batch\"][-1]\n        self.assertEqual(batch_row[\"kind\"], \"request\")\n        self.assertEqual(batch_row[\"stage\"], \"act\")\n        self.assertTrue(baseline <= set(batch_row),\n                        \"feed fields may only be added, never removed\")\n\n        # Shape only: the step argument text never reaches the feed\n        # (runcontrol.note_request keeps the shape, never the value).\n        self.assertNotIn(\"s3cret\", json.dumps(feed))\n\n\n\n\n    def test_desktop_batch_audit_written_entry_params_stay_empty(self):\n        # b5t2c (A): the audit journal NEVER persists step arguments. Pinned\n        # against audit.py's WRITTEN entry (_on_event: \"params\": {} at :127),\n        # not the record() call site (which does receive req.params).\n        self._mode(PermissionMode.FULL)\n        r1, r2 = self._seed((100, 77, \"s00000042:1\"), (100, 77, \"s00000042:2\"))\n        params = self._batch([(r1, \"click\", {\"count\": 2}),\n                              (r2, \"type_text\", {\"text\": \"s3cret-value\"})])\n        with self._patch_try_call(_ok_batch_reply(\n                [_row(0, \"click\"), _row(1, \"type_text\")])):\n            response = self.call(\"desktop.batch\", params)\n        self.assertTrue(response.ok, response.error)\n        written = [e for e in self.d.audit.tail(50)\n                   if e[\"method\"] == \"desktop.batch\"]\n        self.assertEqual(len(written), 1)\n        self.assertEqual(written[0][\"params\"], {})      # audit.py:127 pin\n        self.assertNotIn(\"s3cret\",\n                         self.d.audit.path.read_text(encoding=\"utf-8\"))\n\nclass TestB25bFixRowIndexing(_BatchDaemonBase):\n    \"\"\"b25b-fix F1/F3 (2026-10-12): fa6ec59 mapped run_steps reply rows by\n    TOOL NAME (batch.py: `next((r for r in rows if r.get(\"tool\") ==\n    step[\"tool\"]), None)`), so a repeated tool reused the FIRST row of that\n    tool -- a failed step was reported ok with an earlier step's message\n    (false success), and a step the adapter never ran was reported ok too.\n    Rows now map STRICTLY by the adapter's row \"index\"; a step whose index\n    has no row reports ok:false / effect \"none\" / \"not executed (the batch\n    stopped at step {failed_step})\". F3: the exe's hello advertises\n    run_steps and driver_backend.py is byte-identical to 8f63cba, so the\n    PLAIN capabilities gate applies -- no run_steps bypass.\"\"\"\n\n    def _stopped_reply(self, rows, failed_step):\n        \"\"\"A run_steps reply whose batch stopped at failed_step: rows only\n        for the executed prefix, failed_step announced in the result.\"\"\"\n        reply = _ok_batch_reply(rows)\n        reply[\"result\"][\"failed_step\"] = failed_step\n        return reply\n\n    def test_repeated_type_text_second_fails(self):\n        \"\"\"F1: three type_text steps, the second fails, the third never\n        runs. Row 1 must keep ITS OWN failure message (fa6ec59 handed it\n        row 0's success), and row 2 must be honestly not-executed.\"\"\"\n        self._mode(PermissionMode.FULL)\n        r1, r2, r3 = self._seed((100, 77, \"s00000042:1\"), (100, 77, \"s00000043:1\"),\n                                (100, 77, \"s00000044:1\"))\n        rows = [_row(0, \"type_text\", ok=True, message=\"typed into Field\",\n                     effect=\"unknown\"),\n                _row(1, \"type_text\", ok=False,\n                     message=\"element vanished before typing\",\n                     effect=\"none\")]          # NO row for index 2\n        params = self._batch([(r1, \"type_text\", {\"text\": \"a\"}),\n                              (r2, \"type_text\", {\"text\": \"b\"}),\n                              (r3, \"type_text\", {\"text\": \"c\"})])\n        with self._patch_try_call(self._stopped_reply(rows, 1)):\n            response = self.call(\"desktop.batch\", params)\n        self.assertTrue(response.ok, response.error)\n        out = response.result[\"steps\"]\n        self.assertEqual([r[\"ok\"] for r in out], [True, False, False])\n        # Row 1: ITS OWN message, never row 0's.\n        self.assertEqual(out[1][\"message\"], \"element vanished before typing\")\n        self.assertNotEqual(out[1][\"message\"], out[0][\"message\"])\n        # Row 2: no row of its index -> honestly not executed, effect none.\n        self.assertFalse(out[2][\"ok\"])\n        self.assertEqual(out[2][\"effect_state\"], \"none\")\n        self.assertIn(\"not executed\", out[2][\"message\"])\n        self.assertIn(\"step 1\", out[2][\"message\"])\n        self.assertEqual(response.result[\"failed_step\"], 1)\n        # b25b-fix2 (G2): steps [ran=unknown, failed=none, not-run=none] mix\n        # -> \"unknown\", never \"none\" (a step RAN; retry would duplicate).\n        self.assertEqual(response.result[\"effect_state\"], \"unknown\")\n\n    def test_three_set_values_failed_at_one(self):\n        \"\"\"F1 again with set_value (the third tool shape): the adapter\n        stopped at step 1, so step 2 must never be reported ok.\"\"\"\n        self._mode(PermissionMode.FULL)\n        r1, r2, r3 = self._seed((100, 77, \"s00000042:1\"), (100, 77, \"s00000043:1\"),\n                                (100, 77, \"s00000044:1\"))\n        rows = [_row(0, \"set_value\", ok=True, message=\"value set\",\n                     effect=\"unknown\"),\n                _row(1, \"set_value\", ok=False,\n                     message=\"set_value was refused by the control\",\n                     effect=\"none\")]\n        params = self._batch([(r1, \"set_value\", {\"value\": \"one\"}),\n                              (r2, \"set_value\", {\"value\": \"two\"}),\n                              (r3, \"set_value\", {\"value\": \"three\"})])\n        with self._patch_try_call(self._stopped_reply(rows, 1)):\n            response = self.call(\"desktop.batch\", params)\n        self.assertTrue(response.ok, response.error)\n        out = response.result[\"steps\"]\n        self.assertEqual([r[\"ok\"] for r in out], [True, False, False])\n        self.assertIn(\"not executed\", out[2][\"message\"])\n        self.assertIn(\"step 1\", out[2][\"message\"])\n        self.assertEqual(out[2][\"effect_state\"], \"none\")\n        self.assertFalse(out[2][\"ok\"])       # the false-success shape, banned\n\n    def test_false_success_regression_fa6ec59(self):\n        \"\"\"Pin the fa6ec59 BUG SHAPE itself. The old lookup (reproduced\n        inline from git show fa6ec59:src/autoskill/desktop/batch.py) read\n        the FIRST row whose tool matched, so on this reply it reports\n        step 2 -- which never ran -- as ok with row 0's message. The\n        inline legacy lookup must demonstrably false-succeed, and the\n        handler's index mapping must NOT agree with it.\"\"\"\n        self._mode(PermissionMode.FULL)\n        r1, r2, r3 = self._seed((100, 77, \"s00000042:1\"), (100, 77, \"s00000043:1\"),\n                                (100, 77, \"s00000044:1\"))\n        rows = [_row(0, \"click\", ok=True, message=\"on OK in App\",\n                     effect=\"unknown\"),\n                _row(1, \"click\", ok=False, message=\"click missed the element\",\n                     effect=\"none\")]\n        params = self._batch([(r1, \"click\", {}), (r2, \"click\", {}),\n                              (r3, \"click\", {})])\n        with self._patch_try_call(self._stopped_reply(rows, 1)):\n            response = self.call(\"desktop.batch\", params)\n        out = response.result[\"steps\"]\n        # What fa6ec59's tool-name mapping would have said.\n        legacy = [next((r for r in rows if r.get(\"tool\") == step[\"tool\"]), None)\n                  for step in params[\"steps\"]]\n        self.assertEqual([bool(r[\"ok\"]) for r in legacy], [True, True, True],\n                         \"the fa6ec59 lookup must false-succeed on this reply\")\n        self.assertEqual(legacy[2][\"message\"], \"on OK in App\",\n                         \"the never-run step 2 read row 0's row\")\n        # The new index mapping must disagree exactly where the bug was.\n        self.assertNotEqual([r[\"ok\"] for r in out], [r[\"ok\"] for r in legacy])\n        self.assertEqual([r[\"ok\"] for r in out], [True, False, False])\n        self.assertIn(\"not executed\", out[2][\"message\"])\n        self.assertEqual(out[2][\"effect_state\"], \"none\")\n\n    def test_hello_run_steps_advertised(self):\n        \"\"\"F3(a): the REAL exe's hello advertises run_steps, so the plain\n        capabilities gate passes it with no special case. The seam is the\n        test_driver_backend.py construction -- DriverBackend([command])\n        + try_call -- pointed at the real binary (the raw\n        subprocess.run-and-close-stdin shape of test_driver_matrix.py is\n        NOT usable for hello: the EOF shutdown races the hello reply and\n        the exe prints nothing; the backend holds stdin open, which is\n        also exactly how production talks to it).\"\"\"\n        relative = (\"native/driver/autoskill-driver.exe\" if os.name == \"nt\"\n                    else \"native/driver/bin/autoskill-driver\")\n        with patch.dict(os.environ, {\"AUTOSKILL_DRIVER\": \"on\"}):\n            backend = DriverBackend([str(asset(relative))])\n            self.addCleanup(backend.shutdown)\n            reply = backend.try_call(\"hello\")\n        self.assertIsNotNone(reply, \"the real driver must complete its hello\")\n        hello = reply[\"result\"]\n        self.assertEqual(hello[\"protocol\"], 1)\n        capabilities = hello[\"capabilities\"]\n        self.assertIn(\"run_steps\", capabilities)\n        # Additive only: everything fa6ec59 advertised is still there.\n        self.assertLessEqual({\"list_windows\", \"window_state\", \"click\",\n                              \"set_value\", \"type_text\"}, set(capabilities))\n\n    def test_try_call_no_special_case(self):\n        \"\"\"F3(b): driver_backend.py at HEAD is byte-identical to 8f63cba\n        (git diff 8f63cba -- src/autoskill/desktop/driver_backend.py is\n        empty) -- the fa6ec59 `if method == \"run_steps\": pass` bypass is\n        gone. A child whose hello LACKS run_steps must get the plain\n        unsupported_method refusal, effect none, with NOTHING dispatched\n        (at fa6ec59 the bypass let this call through and the child\n        answered ok).\"\"\"\n        fake = r'''\nimport json, sys\nfor line in sys.stdin:\n    req = json.loads(line)\n    if req['method'] == 'hello':\n        result = {'driver': 'fake-b25b', 'os': 'fake', 'protocol': 1,\n                  'capabilities': ['list_windows', 'click']}\n        print(json.dumps({'id': req['id'], 'ok': True, 'result': result}), flush=True)\n        continue\n    print(json.dumps({'id': req['id'], 'ok': True,\n                      'result': {'echo': req['method']}}), flush=True)\n'''\n        with patch.dict(os.environ, {\"AUTOSKILL_DRIVER\": \"on\"}):\n            backend = DriverBackend([sys.executable, \"-u\", \"-c\", fake])\n            self.addCleanup(backend.shutdown)\n            self.assertTrue(backend.available())\n            result = backend.try_call(\n                \"run_steps\", {\"pid\": 100, \"window_id\": 77, \"steps\": []})\n        self.assertIsNotNone(result)\n        self.assertFalse(result[\"ok\"])       # the bypass would answer ok\n        self.assertEqual(result[\"error\"][\"code\"], \"unsupported_method\")\n        self.assertEqual(result[\"error\"][\"effect_state\"], \"none\")\n        self.assertIn(\"does not advertise\", result[\"error\"][\"message\"])\n        # Refused BEFORE dispatch: hello only (id 1), and the child never\n        # saw a run_steps frame (it would have echoed it back).\n        self.assertEqual(backend._next_id, 1)\n        self.assertNotIn(\"run_steps\",\n                         backend.try_call(\"hello\")[\"result\"][\"capabilities\"])\n\n\n\n\nclass TestB25bFix2Aggregate(_BatchDaemonBase):\n    \"\"\"b25b-fix2: G1 - a structured failure report keeps per-step rows (a\n    ran step is NEVER none); G2 - the aggregate truth table (none only if\n    ALL none; committed only if ALL committed; else unknown).\"\"\"\n\n    def setUp(self):\n        super().setUp()\n        from autoskill.desktop import refs as _refs\n        _p = patch.object(_refs, \"DRIVER_SINCE_READS\", False)\n        _p.start()\n        self.addCleanup(_p.stop)\n\n    # --- the aggregate truth table, straight through _map_rows ---\n    def _reply_with_row_effects(self, effects):\n        rows = [_row(i, \"click\", effect=e) for i, e in enumerate(effects)]\n        return _ok_batch_reply(rows)\n\n    def _resolved(self, n):\n        # The daemon-base session's store (the base seeds via _seed; for\n        # the pure _map_rows tests a plain store is enough).\n        store = self.session.ref_store\n        resolved = []\n        for i in range(n):\n            ref = store.add(None, role=\"button\", name=f\"B{i}\",\n                            element_token=f\"s00000042:{i+1}\",\n                            window_pid=100, top_window=77, process=\"app.exe\",\n                            window_title=\"App\")\n            resolved.append((store.resolve(ref),\n                             {\"tool\": \"click\", \"args\": {}}))\n        return resolved\n\n    def test_truth_table_all_none_is_none(self):\n        from autoskill.desktop.batch import _map_rows\n        reply = self._reply_with_row_effects([\"none\", \"none\"])\n        out = _map_rows(reply, self._resolved(2))\n        self.assertEqual(out[\"effect_state\"], \"none\")\n\n    def test_truth_table_all_committed_is_committed(self):\n        from autoskill.desktop.batch import _map_rows\n        reply = self._reply_with_row_effects([\"committed\", \"committed\"])\n        out = _map_rows(reply, self._resolved(2))\n        self.assertEqual(out[\"effect_state\"], \"committed\")\n\n    def test_truth_table_any_mix_is_unknown(self):\n        from autoskill.desktop.batch import _map_rows\n        for effects in ([\"unknown\", \"none\"],          # G2: ran + not-run\n                        [\"committed\", \"unknown\"],\n                        [\"unknown\", \"committed\", \"none\"],\n                        [\"committed\", \"none\"]):\n            with self.subTest(effects=effects):\n                reply = self._reply_with_row_effects(effects)\n                out = _map_rows(reply, self._resolved(len(effects)))\n                self.assertEqual(out[\"effect_state\"], \"unknown\",\n                                 f\"the old min() gave none for {effects}\")\n\n    def test_live06_shape_never_nones_a_ran_step(self):\n        # The exact G1 live shape THROUGH the daemon-level flow: the fixed\n        # adapter returns envelope ok:true with result.ok:false and rows\n        # [index0 ok, index1 failed]; three caller steps. Step 0 RAN\n        # (unknown), steps 1-2 not executed (none), batch UNKNOWN.\n        self._mode(PermissionMode.FULL)\n        r1, r2, r3 = self._seed((100, 77, \"s00000042:1\"),\n                                (100, 77, \"s00000043:1\"),\n                                (100, 77, \"s00000044:1\"))\n        structured_failure = _ok_batch_reply([\n            _row(0, \"type_text\", ok=True,\n                 message=\"Wrote 10 char(s) on pid 31896; verify: confirmed\",\n                 effect=\"unknown\"),\n            _row(1, \"type_text\", ok=False, message=\"element not found\",\n                 effect=\"none\")])\n        structured_failure[\"result\"][\"ok\"] = False\n        structured_failure[\"result\"][\"executed\"] = 1\n        structured_failure[\"result\"][\"failed_step\"] = 1\n        params = self._batch([(r1, \"type_text\", {\"text\": \"a\"}),\n                              (r2, \"type_text\", {\"text\": \"b\"}),\n                              (r3, \"type_text\", {\"text\": \"c\"})])\n        with self._patch_try_call(structured_failure):\n            response = self.call(\"desktop.batch\", params)\n        self.assertTrue(response.ok, response.error)\n        out = response.result[\"steps\"]\n        # Step 0 RAN: unknown with its own message - never none.\n        self.assertEqual(out[0][\"effect_state\"], \"unknown\")\n        self.assertIn(\"Wrote 10 char(s)\", out[0][\"message\"])\n        # Steps 1-2 not executed: none.\n        self.assertEqual([r[\"effect_state\"] for r in out[1:]],\n                         [\"none\", \"none\"])\n        # G2: the batch is UNKNOWN (a step ran), never none.\n        self.assertEqual(response.result[\"effect_state\"], \"unknown\")\n        self.assertFalse(response.result.get(\"ok\", True))\n\n    def test_legacy_envelope_error_keeps_old_behaviour(self):\n        # Envelope ok:false with NO result rows (transport loss / timeout):\n        # today's whole-batch state copy stays; a timeout is unknown for\n        # every step (K2d).\n        self._mode(PermissionMode.FULL)\n        r1, r2 = self._seed((100, 77, \"s00000042:1\"),\n                            (100, 77, \"s00000043:1\"))\n        legacy = {\"ok\": False, \"error\": {\n            \"code\": \"driver_timeout\",\n            \"message\": \"SDK request deadline expired or worker stopped: timed out\",\n            \"effect_state\": \"unknown\",\n            \"wants_foreground\": False, \"stale_element\": False}}\n        params = self._batch([(r1, \"click\", {}), (r2, \"click\", {})])\n        with self._patch_try_call(legacy):\n            response = self.call(\"desktop.batch\", params)\n        self.assertTrue(response.ok, response.error)\n        out = response.result[\"steps\"]\n        self.assertEqual([r[\"effect_state\"] for r in out],\n                         [\"unknown\", \"unknown\"])\n        self.assertEqual(response.result[\"effect_state\"], \"unknown\")\n\n\n\n\nclass TestNoPostBatchRead(_BatchDaemonBase):\n    \"\"\"fx10 (owner 2026-10-29, \"like CUA\"): a desktop.batch is ONE run_steps\n    call. CUA's run_steps reads only when the caller asks for `observe`\n    (batch_tools.rs:486-493), so no window_state follows the reply, no step is\n    upgraded and the observation's tokens stay as they were. Replaces the b25c\n    post-batch read-back (D08).\"\"\"\n\n    def _ref(self, name, index, role=\"textbox\"):\n        store = self.session.ref_store\n        return store.add(None, role=role, name=name,\n                         element_token=f\"s00000042:{index}\",\n                         window_pid=100, top_window=77, process=\"app.exe\",\n                         window_title=\"App\")\n\n    def _run(self, params, batch_reply):\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   side_effect=[batch_reply]) as call:\n            response = self.call(\"desktop.batch\", params)\n        return response, call\n\n    def test_value_steps_make_one_call_and_keep_the_reply(self):\n        self._mode(PermissionMode.FULL)\n        fa = self._ref(\"Field\", 1)\n        fb = self._ref(\"Note\", 2)\n        go = self._ref(\"Go\", 3, role=\"button\")\n        params = self._batch([(fa, \"set_value\", {\"value\": \"x\"}),\n                              (fb, \"type_text\", {\"text\": \"y\"}),\n                              (go, \"click\", {})])\n        batch = _ok_batch_reply([_row(0, \"set_value\", effect=\"unknown\"),\n                                 _row(1, \"type_text\", effect=\"unknown\"),\n                                 _row(2, \"click\", effect=\"unknown\")])\n        response, call = self._run(params, batch)\n        self.assertTrue(response.ok, response.error)\n        self.assertEqual([c[0][0] for c in call.call_args_list], [\"run_steps\"])\n        self.assertEqual([r[\"effect_state\"] for r in response.result[\"steps\"]],\n                         [\"unknown\", \"unknown\", \"unknown\"])\n        self.assertEqual(response.result[\"effect_state\"], \"unknown\")\n        store = self.session.ref_store\n        self.assertEqual([store.resolve(r).element_token for r in (fa, fb, go)],\n                         [\"s00000042:1\", \"s00000042:2\", \"s00000042:3\"])\n\n    def test_cuas_committed_rows_still_fold_to_committed(self):\n        self._mode(PermissionMode.FULL)\n        fa = self._ref(\"Field\", 1)\n        fb = self._ref(\"Note\", 2)\n        params = self._batch([(fa, \"set_value\", {\"value\": \"x\"}),\n                              (fb, \"set_value\", {\"value\": \"y\"})])\n        batch = _ok_batch_reply([_row(0, \"set_value\", effect=\"committed\"),\n                                 _row(1, \"set_value\", effect=\"committed\")])\n        response, call = self._run(params, batch)\n        self.assertTrue(response.ok, response.error)\n        self.assertEqual(call.call_count, 1)\n        self.assertEqual(response.result[\"effect_state\"], \"committed\")\n\n    def test_a_failure_report_makes_no_read(self):\n        self._mode(PermissionMode.FULL)\n        go = self._ref(\"Go\", 2, role=\"button\")\n        fa = self._ref(\"Field\", 1)\n        fb = self._ref(\"Note\", 3)\n        params = self._batch([(go, \"click\", {}),\n                              (fa, \"set_value\", {\"value\": \"x\"}),\n                              (fb, \"type_text\", {\"text\": \"y\"})])\n        batch = _ok_batch_reply([_row(0, \"click\", effect=\"unknown\"),\n                                 _row(1, \"set_value\", effect=\"unknown\")])\n        batch[\"result\"][\"ok\"] = False\n        batch[\"result\"][\"executed\"] = 2\n        batch[\"result\"][\"failed_step\"] = 2\n        response, call = self._run(params, batch)\n        self.assertTrue(response.ok, response.error)\n        self.assertEqual(call.call_count, 1)\n        out = response.result[\"steps\"]\n        self.assertEqual([r[\"effect_state\"] for r in out], [\"unknown\", \"unknown\", \"none\"])\n        self.assertIn(\"not executed\", out[2][\"message\"])\n\n\n\n\nclass DesktopBatchMcpPathTests(_BatchDaemonBase):\n    \"\"\"b25d (task 5.4d): the MCP surface. tools/call for the batch must reach\n    the REGISTERED daemon handler through the same client.call transport the\n    CLI uses - not a private route - with arguments validated by the catalogue\n    schema (tool_arguments) and the session resolved by the tool's session\n    flag. The seam: autoskill.client.call is replaced by an in-process\n    forwarder into this harness's real Daemon (the handler table is the\n    production one handlers.py registered).\"\"\"\n\n    def test_tools_call_reaches_the_registered_batch_handler(self):\n        from autoskill.mcp_server import McpServer\n\n        r1, r2 = self._seed((100, 77, \"s00000042:1\"), (100, 77, \"s00000042:2\"))\n        server = McpServer(profile=\"all\", home=self.home)\n        sent = []\n\n        def forward(method, params=None, *, session=None, home=None,\n                    timeout=300.0, start_if_missing=True):\n            sent.append((method, params, session))\n            reply = self.d.handle(Request(method=method, params=params or {},\n                                          session=session, id=\"mcp\"))\n            return json.loads(reply.to_line())\n\n        arguments = {\"steps\": [{\"ref\": r1, \"tool\": \"click\", \"args\": {}},\n                               {\"ref\": r2, \"tool\": \"click\", \"args\": {}}],\n                     \"delay_ms\": 50, \"session_id\": self.session.id}\n        with patch(\"autoskill.client.call\", side_effect=forward), \\\n                self._patch_try_call(_ok_batch_reply(\n                    [_row(0, \"click\"), _row(1, \"click\")])) as wire:\n            out = server._call_tool({\"name\": \"batch\", \"arguments\": arguments})\n\n        self.assertFalse(out.get(\"isError\"),\n                         out.get(\"content\", [{}])[0].get(\"text\"))\n        # The transport saw exactly one daemon call: the batch METHOD (the\n        # catalogue routed the name), carrying the schema-validated\n        # arguments and the session the tool's session flag resolved.\n        self.assertEqual([m for m, _, _ in sent], [\"desktop.batch\"])\n        method, params, session = sent[0]\n        self.assertEqual(session, self.session.id)\n        self.assertEqual(params[\"delay_ms\"], 50)\n        self.assertEqual([(s[\"ref\"], s[\"tool\"], s[\"args\"])\n                          for s in params[\"steps\"]],\n                         [(r1, \"click\", {}), (r2, \"click\", {})])\n        # The REAL registered handler ran: only run_batch resolves @eN refs\n        # to driver element_tokens on the run_steps wire. Clicks-only, so\n        # no value step exists and exactly ONE driver call is made (b25c\n        # read-back triggers only on executed ok set_value/type_text).\n        wire.assert_called_once()\n        self.assertEqual(wire.call_args_list[0][0][0], \"run_steps\")\n        sent_wire = wire.call_args_list[0][0][1]\n        self.assertEqual((sent_wire[\"pid\"], sent_wire[\"window_id\"]), (100, 77))\n        self.assertEqual([s[\"args\"][\"element_token\"]\n                          for s in sent_wire[\"steps\"]],\n                         [\"s00000042:1\", \"s00000042:2\"])\n        self.assertEqual(sent_wire.get(\"delay_ms\"), 50)\n        # The reply flows back through the MCP result shape: clicks stay\n        # honest unknown, the rows render short.\n        result = out[\"structuredContent\"]\n        self.assertEqual(result[\"effect_state\"], \"unknown\")\n        self.assertEqual([r[\"tool\"] for r in result[\"steps\"]],\n                         [\"click\", \"click\"])\n        self.assertIn(\"effect_state\", out[\"content\"][0][\"text\"])\n        # And the daemon's existing feed writer recorded the batch - the\n        # audit path is the same one the CLI drives.\n        feed = self.call(\"_run.state\").result[\"feed\"]\n        self.assertTrue(any(r.get(\"method\") == \"desktop.batch\" for r in feed))\n\n\n\n\nclass TestB25eOneAskPerBatch(_BatchDaemonBase):\n    \"\"\"b25e (owner decision: ONE ask per batch in every mode): daemon.py's\n    method-level ask for desktop.batch now lists every step (batch.\n    describe_steps), and its grant is carried into the handler for THAT\n    request only (a ContextVar set/reset around dispatch), so run_batch\n    skips its own combined ask under the token -- the per-step checks\n    still run and a DENIED step still refuses via enforce(). Guarded\n    INPUT batches stay at ZERO asks; every other method's ask detail\n    stays byte-identical to the pre-b25e f-string.\"\"\"\n\n    def _ref(self, name, index, role=\"textbox\", observed=\"\"):\n        \"\"\"A driver-token ref in the ONE batch window (pid 100 / window\n        77) with a controllable role/name -- the ask detail must name\n        them (the base _seed's fixed 'Target N' names cannot).\"\"\"\n        store = self.session.ref_store\n        return store.add(None, role=role, name=name,\n                         element_token=f\"s00000042:{index}\",\n                         window_pid=100, top_window=77, process=\"app.exe\",\n                         window_title=\"App\", observed_value=observed)\n\n    def _answer_every_ask(self, granted, timeout=10.0):\n        \"\"\"Answer EVERY ask that parks during the request, by its\n        pending token (the _answer_pending route), recording each\n        DISTINCT token. Unlike the base's one-shot _answer_when_parked\n        this keeps answering: at 65dcb84 (where a second, handler-level\n        ask parks after the outer one is granted) the request still\n        completes, so a red there is about the ask COUNT and DETAIL,\n        not a timeout decline.\"\"\"\n        done = threading.Event()\n        parked = {}\n\n        def answerer():\n            deadline = time.monotonic() + timeout\n            while not done.is_set() and time.monotonic() < deadline:\n                for c in self.d.confirmations.pending():\n                    if c[\"token\"] not in parked:\n                        parked[c[\"token\"]] = c\n                        self.d.confirmations.answer(c[\"token\"], granted)\n                time.sleep(0.02)\n\n        answerer_thread = threading.Thread(target=answerer, daemon=True)\n        answerer_thread.start()\n        return done, answerer_thread, parked\n\n    def _approval_rows(self):\n        feed = self.call(\"_run.state\", session=None).result[\"feed\"]\n        return [r for r in feed if r.get(\"kind\") == \"approval\"]\n\n    def test_strict_mode_exactly_one_ask_listing_steps(self):\n        fa = self._ref(\"Field\", 1)                  # textbox 'Field'\n        go = self._ref(\"Go\", 2, role=\"button\")      # button 'Go'\n        self._mode(PermissionMode.STRICT)\n        params = self._batch([(fa, \"type_text\", {\"text\": \"hi\"}),\n                              (go, \"click\", {})], delay_ms=10)\n        mapped, forcing = self._force_step_confirmation()\n        asks, ask_spy = self._spy_asks()\n        done, answerer, parked = self._answer_every_ask(True)\n        batch = _ok_batch_reply([_row(0, \"type_text\"), _row(1, \"click\")])\n        ws = {\"ok\": True, \"result\": {\n            \"window_id\": 77, \"pid\": 100, \"snapshot_id\": \"s00000043\",\n            \"elements\": [{\"element_index\": 1,\n                          \"element_token\": \"s00000043:1\",\n                          \"role\": \"Edit\", \"label\": \"Field\", \"depth\": 1,\n                          \"value\": \"hi\"}],\n            \"total_element_count\": 1, \"returned_element_count\": 1,\n            \"tree_format\": \"elements\"}}\n        with forcing, ask_spy, patch(\n                \"autoskill.desktop.driver_backend.try_call\",\n                side_effect=[batch, ws]) as call:\n            response = self.call(\"desktop.batch\", params)\n        done.set()\n        answerer.join(2)\n        self.assertTrue(response.ok, response.error)\n        # The per-step checks still ran under the grant (a DENIED step\n        # would have refused via enforce()); type_text -> desktop.type.\n        self.assertEqual(mapped, [\"desktop.type\", \"desktop.click\"])\n        # EXACTLY ONE confirmation requested for the whole request, on\n        # BOTH spy channels: the broker ask ...\n        self.assertEqual(len(asks), 1)\n        self.assertEqual(len(parked), 1)\n        # ... and the feed's \"asked\" row (the daemon's method-level note).\n        asked_rows = [r for r in self._approval_rows()\n                      if r.get(\"method\") == \"desktop.batch\"]\n        self.assertEqual([r.get(\"scope\") for r in asked_rows], [\"asked\"])\n        # The one ask is the daemon's method-level ask listing BOTH steps.\n        self.assertEqual(asks[0][\"method\"], \"desktop.batch\")\n        self.assertTrue(asks[0][\"detail\"].startswith(\"desktop.batch steps: \"))\n        self.assertIn(f\"type_text on {fa} textbox 'Field'\", asks[0][\"detail\"])\n        self.assertIn(f\"click on {go} button 'Go'\", asks[0][\"detail\"])\n        self.assertNotIn(\"requiring approval\", asks[0][\"detail\"])\n        # Allow-once granted -> the batch RUNS: one run_steps carrying\n        # both element tokens; fx10: no read-back follows (as CUA).\n        self.assertEqual(call.call_count, 1)\n        self.assertEqual(call.call_args_list[0][0][0], \"run_steps\")\n        self.assertEqual([s[\"args\"][\"element_token\"]\n                          for s in call.call_args_list[0][0][1][\"steps\"]],\n                         [\"s00000042:1\", \"s00000042:2\"])\n\n    def test_strict_mode_decline_sends_nothing(self):\n        fa = self._ref(\"Field\", 1)\n        go = self._ref(\"Go\", 2, role=\"button\")\n        self._mode(PermissionMode.STRICT)\n        params = self._batch([(fa, \"type_text\", {\"text\": \"hi\"}),\n                              (go, \"click\", {})])\n        mapped, forcing = self._force_step_confirmation()\n        asks, ask_spy = self._spy_asks()\n        done, answerer, _parked = self._answer_every_ask(False)  # Decline\n        with forcing, ask_spy, self._patch_try_call(\n                _ok_batch_reply([_row(0, \"type_text\"),\n                                 _row(1, \"click\")])) as call:\n            response = self.call(\"desktop.batch\", params)\n        done.set()\n        answerer.join(2)\n        self.assertEqual(len(asks), 1)     # the single method-level ask\n        self.assertFalse(response.ok)\n        self.assertEqual(response.error[\"code\"], \"confirmation_declined\")\n        self.assertEqual(response.error[\"effect_state\"], \"none\")\n        call.assert_not_called()           # try_call NEVER called\n        self.assertEqual(mapped, [])       # declined before the handler\n        self.assertEqual(self.d.confirmations.pending(), [])\n\n    def test_guarded_zero_asks_unchanged(self):\n        \"\"\"The D2 pin shape, restated for b25e: a guarded INPUT batch\n        stays at ZERO asks -- the method-level ask never fires (INPUT is\n        not in GUARDED_CONFIRM_RISKS), so no step list is built and no\n        token is ever set.\"\"\"\n        fa = self._ref(\"Field\", 1)\n        go = self._ref(\"Go\", 2, role=\"button\")\n        self._mode(PermissionMode.GUARDED)\n        params = self._batch([(fa, \"type_text\", {\"text\": \"t\"}),\n                              (go, \"click\", {})], delay_ms=10)\n        asks, ask_spy = self._spy_asks()\n        with ask_spy, self._patch_try_call(_ok_batch_reply(\n                [_row(0, \"type_text\"), _row(1, \"click\")])) as call:\n            response = self.call(\"desktop.batch\", params)\n        self.assertTrue(response.ok, response.error)\n        self.assertEqual(asks, [])                    # ZERO asks\n        self.assertEqual(self.d.confirmations.pending(), [])\n        self.assertEqual(self._approval_rows(), [])   # no feed approvals\n        self.assertEqual(call.call_count, 1,  # fx10: the send only, no read-back (as CUA)\n                         'the batch send and no window_state read')\n        self.assertEqual(call.call_args_list[0][0][0], \"run_steps\")\n        self.assertEqual(response.result.get(\"effect_state\"), \"unknown\")\n\n    def test_grant_does_not_leak(self):\n        from autoskill.desktop.batch import (_REQUEST_ASK_GRANTED,\n                                             reset_request_ask_granted,\n                                             set_request_ask_granted)\n        # The leak unit: the daemon's exact pairing (set around dispatch,\n        # reset in the finally) leaves the ContextVar at its default.\n        self.assertFalse(_REQUEST_ASK_GRANTED.get())\n        token = set_request_ask_granted()\n        self.assertTrue(_REQUEST_ASK_GRANTED.get())\n        reset_request_ask_granted(token)\n        self.assertFalse(_REQUEST_ASK_GRANTED.get())\n\n        # The flow: a granted strict batch, then a SECOND strict request\n        # -- its OWN ask must park again (the token was reset, not left\n        # set by the first grant).\n        go = self._ref(\"Go\", 2, role=\"button\")\n        self._mode(PermissionMode.STRICT)\n        params = self._batch([(go, \"click\", {})])\n        mapped, forcing = self._force_step_confirmation()\n        asks, ask_spy = self._spy_asks()\n        done, answerer, parked = self._answer_every_ask(True)\n        with forcing, ask_spy, patch(\n                \"autoskill.desktop.driver_backend.try_call\",\n                side_effect=[_ok_batch_reply([_row(0, \"click\")]),\n                             _ok_batch_reply([_row(0, \"click\")])]) as call:\n            first = self.call(\"desktop.batch\", params)\n            second = self.call(\"desktop.batch\", params)\n        done.set()\n        answerer.join(2)\n        self.assertTrue(first.ok, first.error)\n        self.assertTrue(second.ok, second.error)\n        self.assertEqual(mapped, [\"desktop.click\", \"desktop.click\"])\n        # TWO asks total across TWO requests -- one per request, never\n        # zero (a leak) and never two-per-request (the old double ask).\n        self.assertEqual(len(asks), 2)\n        self.assertEqual([a[\"method\"] for a in asks],\n                         [\"desktop.batch\", \"desktop.batch\"])\n        self.assertEqual(len(parked), 2)   # two DISTINCT pending tokens\n        self.assertEqual([c[0][0] for c in call.call_args_list],\n                         [\"run_steps\", \"run_steps\"])  # both batches ran\n        self.assertFalse(_REQUEST_ASK_GRANTED.get())  # nothing left set\n\n    def test_non_batch_detail_byte_identical(self):\n        go = self._ref(\"Go\", 2, role=\"button\")\n        self._mode(PermissionMode.STRICT)\n        asks, ask_spy = self._spy_asks()\n        done, answerer, _parked = self._answer_every_ask(True)\n        click_reply = {\"ok\": True, \"result\": {\"effect\": \"confirmed\",\n                                              \"evidence\": \"ack\"}}\n        with ask_spy, patch(\"autoskill.desktop.driver_backend.try_call\",\n                            return_value=click_reply) as call:\n            response = self.call(\"desktop.click\", {\"ref\": go})\n        done.set()\n        answerer.join(2)\n        self.assertTrue(response.ok, response.error)\n        self.assertEqual(len(asks), 1)\n        # EXACTLY the pre-b25e f-string (daemon.py:703), byte for byte:\n        # the method, the ' / '-joined target, the em-dash, the engine's\n        # reason. No step list -- the b25e branch is desktop.batch-only.\n        self.assertEqual(asks[0][\"detail\"],\n                         \"desktop.click on app.exe / App \\u2014 \"\n                         \"strict mode: every action is confirmed\")\n        call.assert_called_once()\n        self.assertEqual(call.call_args[0][0], \"click\")\n\n    def test_batch_mirror_file_written_argument_free(self):\n        fa = self._ref(\"Field\", 1)                  # textbox 'Field'\n        go = self._ref(\"Go\", 2, role=\"button\")      # button 'Go'\n        self._mode(PermissionMode.STRICT)\n        params = self._batch([(fa, \"type_text\", {\"text\": \"s3cret-text\"}),\n                              (go, \"click\", {\"count\": 2, \"button\": \"right\"})],\n                             delay_ms=10)\n        asks, ask_spy = self._spy_asks()\n        batch = _ok_batch_reply([_row(0, \"type_text\"), _row(1, \"click\")])\n        ws = {\"ok\": True, \"result\": {\n            \"window_id\": 77, \"pid\": 100, \"snapshot_id\": \"s00000043\",\n            \"elements\": [{\"element_index\": 1,\n                          \"element_token\": \"s00000043:1\",\n                          \"role\": \"Edit\", \"label\": \"Field\", \"depth\": 1,\n                          \"value\": \"s3cret-text\"}],\n            \"total_element_count\": 1, \"returned_element_count\": 1,\n            \"tree_format\": \"elements\"}}\n        mirror_path = self.d.home / \"confirmations.json\"\n        out = {}\n\n        def run():\n            with ask_spy, patch(\n                    \"autoskill.desktop.driver_backend.try_call\",\n                    side_effect=[batch, ws]):\n                out[\"response\"] = self.call(\"desktop.batch\", params)\n\n        t = threading.Thread(target=run)\n        t.start()\n        data = None\n        deadline = time.monotonic() + 5\n        while time.monotonic() < deadline:\n            if mirror_path.exists():\n                try:\n                    data = json.loads(mirror_path.read_text(encoding=\"utf-8\"))\n                except (OSError, ValueError):\n                    data = None\n                if data:\n                    break\n            time.sleep(0.02)\n        self.assertIsNotNone(data, \"the mirror must be written while the ask parks\")\n        self.assertEqual(len(data), 1)\n        # LIVE (in-memory, dashboard/status surface): each step's own args.\n        self.assertEqual(len(asks), 1)\n        self.assertIn(f\"type_text on {fa} textbox 'Field' \"\n                      \"(args: text='s3cret-text')\", asks[0][\"detail\"])\n        self.assertIn(f\"click on {go} button 'Go' \"\n                      \"(args: count=2, button='right')\", asks[0][\"detail\"])\n        # MIRROR (the file): exactly today's argument-free text, no values.\n        self.assertEqual(data[0][\"method\"], \"desktop.batch\")\n        self.assertEqual(data[0][\"detail\"],\n                         f\"desktop.batch steps: type_text on {fa} textbox \"\n                         f\"'Field'; click on {go} button 'Go'\")\n        self.assertNotIn(\"s3cret\", mirror_path.read_text(encoding=\"utf-8\"))\n        self.d.confirmations.answer(data[0][\"token\"], True)\n        t.join(timeout=10)\n        self.assertTrue(out[\"response\"].ok, out[\"response\"].error)\n\n\nif __name__ == \"__main__\":  # pragma: no cover\n    unittest.main()\n");
